#include "json.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <cmath>
using J=nlohmann::json; namespace fs=std::filesystem;
J read(fs::path p){std::ifstream f(p);J j;f>>j;return j;}
double diff(const J&a,const J&b){if(a.is_array()){if(a.size()!=b.size())throw std::runtime_error("size");double e=0;for(size_t i=0;i<a.size();++i)e=std::max(e,diff(a[i],b[i]));return e;}return std::abs(a.get<double>()-b.get<double>());}
int main(int argc,char**argv){fs::path p=argv[1];J counts=J::object(),eq=J::array();double low=1e20,high=0;auto rows=read(p/"results/SUMMARY.json");for(auto&r:rows){std::string m=r["mode"],v=r["verdict"];if(!counts[m].contains(v))counts[m][v]=0;counts[m][v]=counts[m][v].get<int>()+1;double t=r["compute_s"];low=std::min(low,t);high=std::max(high,t);}for(std::string m:{"free","center"}){auto a=read(p/"results/static"/m/"result.json"),b=read(p/"static_reference"/m/"result.json");J e={{"mode",m}};for(std::string k:{"initial_variables","variables","durations","coefficients","objective"}){e[k]=diff(a[k],b[k]);if(e[k].get<double>()>1e-10)throw std::runtime_error("Static equivalence failed");}eq.push_back(e);}J summary={{"counts",counts},{"static_equivalence",eq},{"minimum_compute_s",low},{"maximum_compute_s",high},{"complete",rows.size()==44}};std::ofstream(p/"AUDIT.json")<<summary.dump(2)<<'\n';std::cout<<summary.dump(2)<<'\n';auto own=read(fs::path(argv[2])/"results/SUMMARY.json");std::ofstream o(p/"COMPARISON.md");o<<"# 同场景规划结果\n\n本文：原八配置独立初值，动力学权重1000；TOGT：作者单初值，动力学权重1。两者不是相同求解预算或相同软目标的消融。统一布局、运动、QuadA、规划球0.20m及实体碰撞球0.15m；作者基线保留其原MINCO及停止条件。仅规划，不是实飞。碰撞轨迹仍列时间，不能作为有效竞速成绩。本文数据引用已完成批次，未重算。\n\n|条件|本文自由/s|本文中心/s|动态TOGT自由/s|动态TOGT中心/s|\n|---|---:|---:|---|---|\n"<<std::fixed<<std::setprecision(3);for(auto&r:own){std::string lv=r["level"];o<<"|"<<lv<<"|"<<r["methods"]["ours"]["nominal_time_s"].get<double>()<<"|"<<r["methods"]["center"]["nominal_time_s"].get<double>();for(std::string m:{"free","center"})for(auto&v:rows)if(v["level"]==lv&&v["mode"]==m){o<<"|";if(v["verdict"]!="通过")o<<v["verdict"].get<std::string>()<<"（";o<<v["trajectory_s"].get<double>();if(v["verdict"]!="通过")o<<"）";}o<<"|\n";}}
